<body class="dark-theme">

<div id="header">
    <h1>2048</h1>
    <div class="controls">
        <div id="score-container"><span id="score-label">Score:</span><span id="score-val">0</span></div>
        <button id="reset-btn">New Game</button>
    </div>
</div>

<div id="board-wrapper">
    <!-- Grid is populated by JS -->
    <div id="board" class="grid"></div>
</div>

<script>
(function() {
    const SIZE = 4;

    // State variables
    let gameBoard = [];
    let currentScore = 0;

    // DOM Elements
    const boardEl = document.getElementById('board');
    const scoreEl = document.getElementById('score-val');

    function initGrid() {
        boardEl.innerHTML = '';
        for(let i=0; i<SIZE*SIZE; i++) {
            let cell = document.createElement('div');
            cell.className = 'cell';
            // We will assign data-value attributes later or just render via state. 
            // Using direct divs inside container is easiest to update classes/text in place without full re-render logic complexity if we map by index.
            boardEl.appendChild(cell);
        }
    }

    function spawnTile() {
        const emptyCells = [];
        for(let r=0; r<SIZE; r++) {
            for(let c=0; c<SIZE; c++) {
                if(gameBoard[r][c] === 0) emptyCells.push({r,c});
            }
        }
        if(emptyCells.length > 0) {
            const rand = Math.floor(Math.random() * emptyCells.length);
            const pos = emptyCells[rand];
            // Chance for 4 is small but not impossible; default to 2.
            gameBoard[pos.r][pos.c] = (Math.random() < 0.1) ? 4 : 2; 
        }
    }

    function resetGame() {
        currentScore = 0;
        updateScoreDisplay();

        // Initialize empty board with exactly 2 tiles
        gameBoard = Array.from({ length: SIZE }, () => Array(SIZE).fill(0));
        spawnTile();
        spawnTile();

        render();
    }

    function updateScoreDisplay() {
        scoreEl.textContent = currentScore;
    }

    // Helper to deep compare arrays
    function boardsEqual(a, b) {
        if (!a || !b) return false;
        for(let r=0; r<SIZE; r++) {
            if(!Array.isArray(b[r])) return false;
            if(a[r].length !== b[r].length) return false;
            for(let c=0; c<a[r].length; c++) {
                if(a[r][c] !== b[r][c]) return false;
            }
        }
        return true;
    }

    // Helper: Process a line as sliding towards index 0 (Left logic on the array representation).
    function getLineStats(line, reverse=false) {
        let arr = [...line];
        if(reverse) arr.reverse(); // Reversing input so that target becomes start

        let vals = arr.filter(x => x !== 0);
        const res = [];
        for(let i=0; i<vals.length; ) {
            if(i+1 < vals.length && vals[i] === vals[i+1]) {
                const sum = vals[i]*2;
                currentScore += sum; // Add score on merge
                res.push(sum);
                i+=2; // Skip next, it's merged into this one
            } else {
                res.push(vals[i]);
                i++;
            }
        }

        while(res.length < arr.length) res.push(0);

        if(reverse) res.reverse(); // Restore original direction order after processing logic
        return res;
    }

    function move(direction) {
        // Capture old state before any modifications to check for changes later.
        const oldState = JSON.parse(JSON.stringify(gameBoard));

        let didChange = false;

        if (direction === 'left' || direction === 'right') {
            for(let r=0; r<SIZE; r++) {
                // Process row based on direction
                gameBoard[r] = getLineStats(gameBoard[r], direction === 'right');
            }
        } else if (direction === 'up' || direction === 'down') {
            for(let c=0; c<SIZE; c++) {
                let line = [];
                // Extract column from board into a temporary array to process logic
                for(let r=0; r<SIZE; r++) line.push(gameBoard[r][c]);

                if(direction === 'up') {
                    const newLine = getLineStats(line, false); 
                    for(let r=0; r<SIZE; r++) gameBoard[r][c] = newLine[r];
                } else { // down
                    const newLine = getLineStats(line, true);
                    for(let r=0; r<SIZE; r++) gameBoard[r][c] = newLine[r];
                }
            }
        }

        // Check if the board changed compared to snapshot before moves.
        didChange = !boardsEqual(oldState, gameBoard);

        if(didChange) {
            spawnTile();
            updateScoreDisplay();
            render();
            return true;
        } else {
            // Move resulted in no change (no sliding possible). 
            // Note: Score was not incremented because that happens inside getLineStats on merge.
            // If board state didn't change, likely no merges or slides occurred that altered the grid representation.
            render(); // Re-render to ensure visual consistency if needed? Not strictly necessary but harmless.
            return false;
        }
    }

    function render() {
        const children = boardEl.children;
        for(let r=0; r<SIZE; r++) {
            for(let c=0; c<SIZE; c++) {
                const val = gameBoard[r][c];
                // Children are divs created in init. Need to update them.
                const index = r * SIZE + c;
                if(children[index]) {
                    children[index].textContent = val === 0 ? '' : val;

                    // Add data attribute for CSS styling convenience (optional but helpful)
                    children[index].dataset.val = val;

                    // Apply background styles based on value to distinguish tiles in dark theme.
                    if (val > 0) {
                        children[index].style.backgroundColor = '#3c3a32'; // Dark tile bg for non-zero
                    } else {
                        // Reset style or set to empty color logic handled by CSS class/data-val usually, but explicit here
                        children[index].style.backgroundColor = ''; 
                    }
                }
            }
        }
    }

    function setBoard(arr) {
        if(!arr || arr.length !== 4 || !Array.isArray(arr[0])) return; // Basic check

        // Deep copy to ensure internal state is isolated from external reference
        gameBoard = JSON.parse(JSON.stringify(arr));

        updateScoreDisplay(); 
        render();
    }

    function getBoard() {
        // Return a fresh deep copy of the current board array
        return JSON.parse(JSON.stringify(gameBoard));
    }

    function getScore() {
        return currentScore;
    }

    // Setup Event Listeners
    document.getElementById('reset-btn').addEventListener('click', resetGame);

    window.addEventListener('keydown', (e) => {
        if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)) {
            e.preventDefault(); // Prevent scrolling default behavior of keys
            move(e.key);
        }
    });

    function initGrid() {
        boardEl.innerHTML = '';
        for(let i=0; i<SIZE*SIZE; i++) {
            let cell = document.createElement('div');
            cell.className = 'cell';
            // Add data-val="0" to mark initial empty state visually via CSS if needed.
            cell.dataset.val = 0; 
            boardEl.appendChild(cell);
        }
    }

    // Expose API on window.game
    window.game = {
        get size() { return SIZE; },
        reset: resetGame,
        move: (dir) => move(dir),
        board: getBoard,
        setBoard: setBoard,
        score: getScore
    };

    // Initialize Grid and start game logic automatically so visual matches expectation.
    initGrid();

    // Start a new game on load to match "A new game starts with..." rule contextually if user opens file directly.
    resetGame();

})();
</script>
</body>
</html>
